import{_ as d,o as a,c as s,a2 as e}from"./chunks/framework.DBKUV7en.js";const f=JSON.parse('{"title":"用語集","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":null}'),r={name:"glossary.md"};function o(n,t,h,c,l,i){return a(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="用語集" tabindex="-1">用語集 <a class="header-anchor" href="#用語集" aria-label="Permalink to &quot;用語集&quot;">​</a></h1><p>この教科書で使う言葉を、素材・抽出・届け方の3つの層と、全体に分けて並べました。右の列から、くわしく書いた回に飛べます。</p><p>言葉づかいは、できるだけそろえています。たとえば、コーヒーの濃さは「濃度」と書いて、「強さ」や「ストレングス」とは書きません。酸っぱさを悪い印象のとき、酸味をよい印象のときに使い分けるのも、僕が決めた約束です。</p><h2 id="全体・考え方" tabindex="-1">全体・考え方 <a class="header-anchor" href="#全体・考え方" aria-label="Permalink to &quot;全体・考え方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>English</th><th>意味</th><th>くわしくは</th></tr></thead><tbody><tr><td>味の3層</td><td>—</td><td>味を、素材・抽出・届け方に分けて考える整理。「個性は素材で決まり、ブレは抽出で起きる」は僕の考察</td><td><a href="/coffee-textbook/ch0/intro">第0回</a></td></tr><tr><td>ドリップグリッド</td><td>—</td><td>抽出の層の地図。横軸が抽出率、縦軸が濃度。家では数字を測れないので、舌で使う</td><td><a href="/coffee-textbook/ch0/intro">第0回</a>、<a href="/coffee-textbook/ch1/sour-bitter">第3回</a></td></tr><tr><td>目安</td><td>—</td><td>18〜22%などの範囲。「理想」や「正解」とは言わない</td><td><a href="/coffee-textbook/ch1/strength-vs-extraction">第4回</a></td></tr><tr><td>基準の一杯</td><td>—</td><td>この教科書で、動かさない土台にするレシピ</td><td><a href="/coffee-textbook/basics/base-recipe">第2回</a></td></tr><tr><td>三点比較</td><td>Triangle test</td><td>3つのうち1つだけ違うものを当てる比べ方。偶然に当たる確率は3分の1</td><td>第22回<span class="soon">(準備中)</span></td></tr></tbody></table><h2 id="抽出の層" tabindex="-1">抽出の層 <a class="header-anchor" href="#抽出の層" aria-label="Permalink to &quot;抽出の層&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>English</th><th>意味</th><th>くわしくは</th></tr></thead><tbody><tr><td>抽出</td><td>Extraction</td><td>粉の成分がお湯に溶け出すこと</td><td><a href="/coffee-textbook/ch1/sour-bitter">第3回</a></td></tr><tr><td>濃度</td><td>TDS</td><td>カップの中の成分の割合(%)。「強さ」とは言わない</td><td><a href="/coffee-textbook/ch1/sour-bitter">第3回</a>、<a href="/coffee-textbook/ch1/strength-vs-extraction">第4回</a></td></tr><tr><td>抽出率</td><td>Extraction Yield (EY)</td><td>粉の重さのうち、溶け出した割合。「収率」とは言わない</td><td><a href="/coffee-textbook/ch1/sour-bitter">第3回</a></td></tr><tr><td>出きっていない</td><td>「未抽出」とは言わない</td><td>抽出率が低い状態。酸っぱい、とがった果実感が出やすい</td><td><a href="/coffee-textbook/ch1/sour-bitter">第3回</a></td></tr><tr><td>よく出ている</td><td>「過抽出」とは言わない</td><td>抽出率が高い状態。まとまる、紅茶っぽい(その先は未確認)</td><td><a href="/coffee-textbook/ch1/sour-bitter">第3回</a></td></tr><tr><td>比率</td><td>Brew ratio</td><td>粉とお湯の割合(例 1:16)。主に濃度を動かす</td><td><a href="/coffee-textbook/ch1/strength-vs-extraction">第4回</a>、第5回<span class="soon">(準備中)</span></td></tr><tr><td>挽き目</td><td>Grind size</td><td>粉の細かさ。細かいほど、抽出が速く進む</td><td>第5回<span class="soon">(準備中)</span></td></tr><tr><td>クリック</td><td>Click</td><td>手挽きミルの目盛りの1段階</td><td>第5回<span class="soon">(準備中)</span>、第17回<span class="soon">(準備中)</span></td></tr><tr><td>湯温</td><td>Water temperature</td><td>お湯の温度。抽出の速さを変える</td><td>第6回<span class="soon">(準備中)</span></td></tr><tr><td>蒸らし</td><td>Bloom</td><td>最初に少量のお湯で粉を湿らせて待つ工程。ガスを逃がすため、と説明される</td><td><a href="/coffee-textbook/basics/base-recipe">第2回</a></td></tr><tr><td>撹拌</td><td>Agitation</td><td>かきまぜること。注ぎ方で流れを作ることも含める</td><td>第5回<span class="soon">(準備中)</span></td></tr><tr><td>ムラ</td><td>Uneven extraction</td><td>粉ごとに出方がバラバラなこと。「不均一抽出」とは言わない</td><td>第7回<span class="soon">(準備中)</span></td></tr><tr><td>微粉</td><td>Fines(ファインズ)</td><td>細かく砕けた粒。目詰まりの原因と言われる。「苦味の元」は管理された研究が見つかっていない</td><td>第7回<span class="soon">(準備中)</span></td></tr><tr><td>目詰まり</td><td>Clogging</td><td>粉の層で水が通りにくくなること</td><td>第7回<span class="soon">(準備中)</span></td></tr><tr><td>透過式</td><td>Percolation</td><td>お湯が粉の層を通り抜ける淹れ方(ハンドドリップ)</td><td><a href="/coffee-textbook/basics/how-drip-works">第1回</a></td></tr><tr><td>浸漬</td><td>Immersion</td><td>粉をお湯に浸ける淹れ方(フレンチプレス、水出し)</td><td><a href="/coffee-textbook/basics/how-drip-works">第1回</a></td></tr><tr><td>屈折計</td><td>Refractometer</td><td>濃度(TDS)を測る機械</td><td><a href="/coffee-textbook/basics/base-recipe">第2回</a></td></tr></tbody></table><h2 id="素材の層" tabindex="-1">素材の層 <a class="header-anchor" href="#素材の層" aria-label="Permalink to &quot;素材の層&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>English</th><th>意味</th><th>くわしくは</th></tr></thead><tbody><tr><td>焙煎度</td><td>Roast level</td><td>浅煎りから深煎りまで。浅いほど酸と果実、深いほど苦さとロースト感</td><td>第8回<span class="soon">(準備中)</span></td></tr><tr><td>酸っぱい / 酸味</td><td>—</td><td>悪い印象は「酸っぱい」、よい印象は「酸味」と使い分ける(僕の考察)</td><td><a href="/coffee-textbook/ch1/sour-bitter">第3回</a>、第9回<span class="soon">(準備中)</span></td></tr><tr><td>焙煎日</td><td>Roast date</td><td>豆を焙煎した日。新しすぎても古すぎても、味がまとまらない</td><td>第11回<span class="soon">(準備中)</span></td></tr><tr><td>標高</td><td>Altitude</td><td>栽培した場所の高さ。高いと、酸味と香りの評価が高い傾向</td><td>第11回<span class="soon">(準備中)</span></td></tr><tr><td>精製</td><td>Processing</td><td>果実から豆を取り出す方法</td><td>第12回<span class="soon">(準備中)</span></td></tr><tr><td>ウォッシュド</td><td>Washed</td><td>果肉を取り、発酵させ、水洗いしてから乾かす。すっきりした味の傾向</td><td>第12回<span class="soon">(準備中)</span></td></tr><tr><td>ナチュラル</td><td>Natural</td><td>果実ごと乾かす。甘さと果実感が出る傾向</td><td>第12回<span class="soon">(準備中)</span></td></tr><tr><td>アナエロビック</td><td>Anaerobic</td><td>酸素を断った発酵</td><td>第12回<span class="soon">(準備中)</span></td></tr><tr><td>Nitro Washed</td><td>—</td><td>窒素を使って発酵させ、水洗いした豆(ロースターの説明)</td><td>第12回<span class="soon">(準備中)</span></td></tr><tr><td>共発酵</td><td>Co-fermentation</td><td>果物などを一緒に発酵タンクに入れる。定義は未確定で、賛否がある</td><td>第13回<span class="soon">(準備中)</span></td></tr><tr><td>インフューズド</td><td>Infused</td><td>風味を加えた豆。共発酵との区別があいまい</td><td>第13回<span class="soon">(準備中)</span></td></tr><tr><td>ゲイシャ</td><td>Geisha / Gesha</td><td>エチオピア原産の品種。パナマで有名になった。花や柑橘のような香り</td><td>第14回<span class="soon">(準備中)</span></td></tr><tr><td>カトゥーラ</td><td>Caturra</td><td>背の低いアラビカ種</td><td>第12回<span class="soon">(準備中)</span></td></tr><tr><td>COE</td><td>Cup of Excellence</td><td>生産国ごとの品評会。入賞豆はオークションで売られる</td><td>第11回<span class="soon">(準備中)</span></td></tr><tr><td>SCA / SCAJ</td><td>—</td><td>スペシャルティコーヒー協会 / その日本支部</td><td>第21回<span class="soon">(準備中)</span></td></tr><tr><td>硬度・アルカリ度</td><td>Hardness / Alkalinity</td><td>水の中のミネラルの量 / 酸を中和する力</td><td>第15回<span class="soon">(準備中)</span></td></tr></tbody></table><h2 id="届け方の層" tabindex="-1">届け方の層 <a class="header-anchor" href="#届け方の層" aria-label="Permalink to &quot;届け方の層&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>English</th><th>意味</th><th>くわしくは</th></tr></thead><tbody><tr><td>口当たり</td><td>Mouthfeel(ボディ)</td><td>舌や口で感じる質感(軽い、重い、なめらか)</td><td>第16回<span class="soon">(準備中)</span></td></tr><tr><td>多孔質</td><td>Porous</td><td>細かい孔がたくさんある素材(セラポッタなど)</td><td>第16回<span class="soon">(準備中)</span></td></tr><tr><td>湯通し</td><td>Rinse</td><td>ドリッパーやフィルターを、お湯で温める、濡らす</td><td>第19回<span class="soon">(準備中)</span></td></tr><tr><td>急冷式</td><td>Flash brew(日本式アイス)</td><td>濃く淹れて、氷の上に落として冷やす</td><td>第18回<span class="soon">(準備中)</span></td></tr><tr><td>飲む温度</td><td>Serving temperature</td><td>味見のときの温度。酸っぱさなどの感じ方が変わる</td><td>第22回<span class="soon">(準備中)</span></td></tr></tbody></table><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><p>用語の意味は、各回の本文と出典にそろえています。研究の条件は<a href="/coffee-textbook/appendix/studies">付録</a>にまとめています。</p><p>次は、<a href="/coffee-textbook/ch0/intro">この教科書について</a>に戻って、読む順番を確かめてみてください。</p>',14)])])}const b=d(r,[["render",o]]);export{f as __pageData,b as default};
